fn is_pascal_case(name: &str) -> bool {
    !name.is_empty() && name == name.to_upper_camel_case()
}

fn is_snake_case(name: &str) -> bool {
    !name.is_empty() && name == name.to_snake_case()
}

fn is_forbidden_name(name: &str) -> Option<&'static str> {
    let lower = name.to_lowercase();
    for &kw in RUST_RESERVED {
        if lower == kw.to_lowercase() {
            return Some("Rust reserved keyword");
        }
    }
    for &kw in CPP_RESERVED {
        if lower == kw.to_lowercase() {
            return Some("C++ reserved keyword");
        }
    }
    for &kw in QT_RESERVED {
        if lower == kw.to_lowercase() {
            return Some("Qt reserved identifier");
        }
    }
    None
}

/// C48 — groups entities whose generated collection identifier is the same.
///
/// Generated code names a collection after the entity it holds, pluralized: an
/// entity `Entity` becomes the `entities` table on the store. `naming::to_plural`
/// is not injective — `Base` and `Basis` both give `bases` — so two entity names
/// that C04 accepts as distinct can still produce a single identifier, which
/// rustc then rejects inside generated code with nothing pointing back at the
/// manifest.
///
/// Each entry of `entities` is `(name, only_for_heritage)`. Heritage-only
/// entities are skipped: the generators never materialize them, so they own no
/// collection. One narrow exception is knowingly not covered: an entity-typed
/// *field* pointing at a heritage entity pulls that entity into the generation
/// snapshot so templates can resolve the field's type (`rust_code_generator.rs`,
/// the `all_entities` branch), which gives it a store field after all. Reporting
/// a critical for every heritage entity would be a false positive on the common
/// case, so this rule prefers the miss.
///
/// The snake-case step is applied here rather than by the caller so
/// it cannot drift from the `heck::AsSnakeCase` the generators feed to the
/// pluralizer. Entities sharing one name are counted once — that is C04's
/// business, not this rule's. Groups, and the names inside them, are sorted so
/// the reported message does not depend on iteration order.
fn collection_name_collisions(entities: &[(&str, bool)]) -> Vec<(String, Vec<String>)> {
    let mut by_collection: HashMap<String, Vec<String>> = HashMap::new();
    for (name, only_for_heritage) in entities {
        if *only_for_heritage || name.is_empty() {
            continue;
        }
        by_collection
            .entry(naming::to_plural(&name.to_snake_case()))
            .or_default()
            .push((*name).to_string());
    }

    let mut collisions: Vec<(String, Vec<String>)> = by_collection
        .into_iter()
        .filter_map(|(collection, mut names)| {
            names.sort();
            names.dedup();
            (names.len() > 1).then_some((collection, names))
        })
        .collect();
    collisions.sort();
    collisions
}

/// Renders entity names as `'Base' and 'Basis'`, or `'A', 'B' and 'C'`.
fn join_quoted_names(names: &[String]) -> String {
    match names.split_last() {
        Some((last, [])) => format!("'{}'", last),
        Some((last, head)) => {
            let head: Vec<String> = head.iter().map(|n| format!("'{}'", n)).collect();
            format!("{} and '{}'", head.join(", "), last)
        }
        None => String::new(),
    }
}

/// Validate enum_values for both entity fields and DTO fields.
/// Supports simple variants (`Active`), tuple variants (`Text(String)`),
/// and struct variants (`Image { name: String, width: i64 }`).
fn validate_enum_values(
    vals: &[String],
    context: &str, // e.g. "Entity 'Foo', field 'bar'" or "DTO 'Baz', field 'qux'"
    entity_names: &HashSet<String>,
    enum_names: &HashSet<String>,
    has_cpp_target: bool,
    critical_errors: &mut Vec<String>,
) {
    for (idx, val) in vals.iter().enumerate() {
        if val.is_empty() {
            critical_errors.push(format!("{}: enum_values contains an empty value", context));
            continue;
        }

        match enum_variant_parser::parse_enum_variant(val) {
            Ok(parsed) => {
                // Variant name must be PascalCase
                if !is_pascal_case(&parsed.name) {
                    critical_errors.push(format!(
                        "{}: enum variant name '{}' must be PascalCase (expected '{}')",
                        context,
                        parsed.name,
                        parsed.name.to_upper_camel_case()
                    ));
                }

                // Complex variants (tuple/struct) are Rust-only
                if has_cpp_target
                    && !matches!(parsed.kind, enum_variant_parser::EnumVariantKind::Simple)
                {
                    critical_errors.push(format!(
                        "{}: complex enum variant '{}' (tuple/struct) is only supported for Rust targets, \
                         but C++ targets are enabled",
                        context, parsed.name
                    ));
                }

                // First variant must be simple (for #[derive(Default)] + #[default])
                if idx == 0 && !matches!(parsed.kind, enum_variant_parser::EnumVariantKind::Simple)
                {
                    critical_errors.push(format!(
                        "{}: the first enum value must be a simple variant (no data) \
                         for Default derive support, but '{}' has data",
                        context, parsed.name
                    ));
                }

                // Validate references inside complex variants
                let refs = enum_variant_parser::collect_references(&parsed);
                for ref_name in &refs {
                    if !entity_names.contains(ref_name) && !enum_names.contains(ref_name) {
                        critical_errors.push(format!(
                            "{}: enum variant '{}' references unknown type '{}' \
                             (not a known entity or enum name)",
                            context, parsed.name, ref_name
                        ));
                    }
                }
            }
            Err(e) => {
                critical_errors.push(format!(
                    "{}: invalid enum variant syntax '{}': {}",
                    context, val, e
                ));
            }
        }
    }
}

pub struct CheckUseCase {
    uow_factory: Box<dyn CheckUnitOfWorkFactoryTrait>,
}

impl CheckUseCase {
    pub fn new(uow_factory: Box<dyn CheckUnitOfWorkFactoryTrait>) -> Self {
        CheckUseCase { uow_factory }
    }

    pub fn execute(&mut self) -> Result<CheckReturnDto> {
        let uow = self.uow_factory.create();
        uow.begin_transaction()?;

        let mut warnings: Vec<String> = vec![];
        let mut critical_errors: Vec<String> = vec![];

        // Get root
        let roots = uow.get_all_root()?;
        if roots.is_empty() {
            critical_errors.push("No root found. Is a manifest loaded?".to_string());
            uow.end_transaction()?;
            return Ok(CheckReturnDto {
                warnings,
                critical_errors,
            });
        }
        let root = &roots[0];

        // Get workspace
        let workspace_id = match root.workspace {
            Some(id) => id,
            None => {
                critical_errors.push("Root has no workspace".to_string());
                uow.end_transaction()?;
                return Ok(CheckReturnDto {
                    warnings,
                    critical_errors,
                });
            }
        };
        let workspace = uow
            .get_workspace(&workspace_id)?
            .ok_or(anyhow!("Workspace not found"))?;

        // Get global
        let global = uow.get_global(&workspace.global)?;
        if let Some(global) = &global {
            if global.application_name.is_empty() {
                critical_errors.push("Global: application_name is empty".to_string());
            } else if !is_pascal_case(&global.application_name) {
                critical_errors.push(format!(
                    "Global: application_name '{}' must be PascalCase (expected '{}')",
                    global.application_name,
                    global.application_name.to_upper_camel_case()
                ));
            }
            if global.organisation_name.is_empty() {
                critical_errors.push("Global: organisation_name is empty".to_string());
            }
            if global.organisation_domain.is_empty() {
                critical_errors.push("Global: organisation_domain is empty".to_string());
            }
            if global.language.is_empty() {
                critical_errors.push("Global: language is empty".to_string());
            }
        } else {
            critical_errors.push("Global settings not found".to_string());
        }

        // Detect if C++ targets are active (complex enum variants are Rust-only).
        // When the language is Rust, complex enums are always allowed regardless of
        // C++ UI flags (the C++ generator won't process Rust-language manifests).
        let is_rust_language = global
            .as_ref()
            .is_some_and(|g| g.language.eq_ignore_ascii_case("rust"));
        // Fetched once: it feeds both the C++-target detection above and the
        // UI-flag/language consistency warning (W05) below.
        let ui = {
            let ui_ids = uow.get_workspace_relationship(
                &workspace_id,
                &common::direct_access::workspace::WorkspaceRelationshipField::UserInterface,
            )?;
            match ui_ids.first() {
                Some(ui_id) => uow.get_user_interface(ui_id)?,
                None => None,
            }
        };
        let has_cpp_target = if is_rust_language {
            false
        } else {
            ui.as_ref()
                .is_some_and(|u| u.cpp_qt_qtwidgets || u.cpp_qt_qtquick)
        };

        // W05 — a rust_* flag on a non-Rust manifest generates nothing. A
        // warning rather than a critical, deliberately: the shipped C++/Qt
        // examples already carry `rust_slint: true`, and `qleany check` has
        // always accepted them.
        if let Some(u) = &ui
            && !is_rust_language
        {
            for (flag, name) in [
                (u.rust_teksilo, "rust_teksilo"),
                (u.rust_slint, "rust_slint"),
                (u.rust_cli, "rust_cli"),
                (u.rust_ios, "rust_ios"),
                (u.rust_android, "rust_android"),
            ] {
                if flag {
                    warnings.push(format!(
                        "UI: {name} is enabled but global.language is not 'rust'; that UI will not be generated"
                    ));
                }
            }
        }

        // ── Entities ──

        let entities = uow.get_entity_multi(&workspace.entities)?;
        let entities: Vec<Entity> = entities.into_iter().flatten().collect();

        // Unique entity names (globally)
        let mut entity_names: HashSet<String> = HashSet::new();
        for entity in &entities {
            if entity.name.is_empty() {
                critical_errors.push(format!("Entity with id {} has an empty name", entity.id));
            } else if !entity_names.insert(entity.name.clone()) {
                critical_errors.push(format!("Duplicate entity name: '{}'", entity.name));
            }
            // Forbidden names
            if let Some(reason) = is_forbidden_name(&entity.name) {
                critical_errors.push(format!(
                    "Entity '{}': name is a {} and cannot be used",
                    entity.name, reason
                ));
            }
            // PascalCase check
            if !entity.name.is_empty() && !is_pascal_case(&entity.name) {
                critical_errors.push(format!(
                    "Entity '{}': name must be PascalCase (expected '{}')",
                    entity.name,
                    entity.name.to_upper_camel_case()
                ));
            }
        }

        // Unique generated collection names. Unique entity names are not enough:
        // generated collections are named after the pluralized entity, and
        // pluralization is not injective.
        let entity_collection_owners: Vec<(&str, bool)> = entities
            .iter()
            .map(|e| (e.name.as_str(), e.only_for_heritage))
            .collect();
        for (collection, names) in collection_name_collisions(&entity_collection_owners) {
            critical_errors.push(format!(
                "Entities {} {} generate the collection name '{}'; rename {}",
                join_quoted_names(&names),
                if names.len() == 2 { "both" } else { "all" },
                collection,
                if names.len() == 2 {
                    "one of them"
                } else {
                    "all but one of them"
                }
            ));
        }

        // Build entity lookup by id
        let entity_by_id: HashMap<EntityId, &Entity> = entities.iter().map(|e| (e.id, e)).collect();

        // Check inheritance cycles
        for entity in &entities {
            if let Some(parent_id) = entity.inherits_from {
                if !entity_by_id.contains_key(&parent_id) {
                    critical_errors.push(format!(
                        "Entity '{}': inherits_from references non-existent entity (id {})",
                        entity.name, parent_id
                    ));
                } else {
                    let mut visited = HashSet::new();
                    visited.insert(entity.id);
                    let mut current_id = Some(parent_id);
                    while let Some(cid) = current_id {
                        if !visited.insert(cid) {
                            critical_errors.push(format!(
                                "Entity '{}': inheritance cycle detected",
                                entity.name
                            ));
                            break;
                        }
                        current_id = entity_by_id.get(&cid).and_then(|e| e.inherits_from);
                    }
                }
            }
        }

        // ── Fields ──

        let all_field_ids: Vec<EntityId> = entities.iter().flat_map(|e| e.fields.clone()).collect();
        let fields = uow.get_field_multi(&all_field_ids)?;
        let fields: Vec<Field> = fields.into_iter().flatten().collect();
        let field_by_id: HashMap<EntityId, &Field> = fields.iter().map(|f| (f.id, f)).collect();

        // Collect all known enum names from entity fields (for cross-reference validation)
        let mut all_enum_names: HashSet<String> = fields
            .iter()
            .filter(|f| f.field_type == FieldType::Enum)
            .filter_map(|f| f.enum_name.clone())
            .collect();

        for entity in &entities {
            if entity.fields.is_empty() && !entity.only_for_heritage {
                warnings.push(format!("Entity '{}' has no fields", entity.name));
            }

            // Collect all fields for this entity (own + inherited)
            let mut all_entity_fields: Vec<&Field> = vec![];

            // Gather inherited fields by walking the inheritance chain
            let mut ancestor_id = entity.inherits_from;
            while let Some(aid) = ancestor_id {
                if let Some(ancestor) = entity_by_id.get(&aid) {
                    for fid in &ancestor.fields {
                        if let Some(f) = field_by_id.get(fid) {
                            all_entity_fields.push(f);
                        }
                    }
                    ancestor_id = ancestor.inherits_from;
                } else {
                    break;
                }
            }

            // Add own fields
            for fid in &entity.fields {
                if let Some(f) = field_by_id.get(fid) {
                    all_entity_fields.push(f);
                }
            }

            // Unique field names within entity (own fields only)
            let mut field_names: HashSet<String> = HashSet::new();
            for field_id in &entity.fields {
                if let Some(field) = field_by_id.get(field_id) {
                    if !field_names.insert(field.name.clone()) {
                        critical_errors.push(format!(
                            "Entity '{}': duplicate field name '{}'",
                            entity.name, field.name
                        ));
                    }

                    // Forbidden field names
                    if let Some(reason) = is_forbidden_name(&field.name) {
                        critical_errors.push(format!(
                            "Entity '{}', field '{}': name is a {} and cannot be used",
                            entity.name, field.name, reason
                        ));
                    }
                    // snake_case check
                    if !field.name.is_empty() && !is_snake_case(&field.name) {
                        critical_errors.push(format!(
                            "Entity '{}', field '{}': name must be snake_case (expected '{}')",
                            entity.name,
                            field.name,
                            field.name.to_snake_case()
                        ));
                    }

                    // A field cannot be both optional and is_list
                    if field.optional && field.is_list {
                        critical_errors.push(format!(
                            "Entity '{}', field '{}': cannot be both optional and is_list",
                            entity.name, field.name
                        ));
                    }

                    // is_list cannot be used with Entity or Enum types
                    if field.is_list
                        && matches!(field.field_type, FieldType::Entity | FieldType::Enum)
                    {
                        critical_errors.push(format!(
                            "Entity '{}', field '{}': is_list cannot be used with type {:?}",
                            entity.name, field.name, field.field_type
                        ));
                    }

                    // list_model / list_model_displayed_field require Entity type + to-many relationship
                    let is_to_many = matches!(
                        field.relationship,
                        FieldRelationshipType::OneToMany
                            | FieldRelationshipType::OrderedOneToMany
                            | FieldRelationshipType::ManyToMany
                    );
                    if (field.list_model || field.list_model_displayed_field.is_some())
                        && !(field.field_type == FieldType::Entity && is_to_many)
                    {
                        critical_errors.push(format!(
                            "Entity '{}', field '{}': list_model or list_model_displayed_field \
                             requires field_type=Entity and relationship in \
                             {{OneToMany, OrderedOneToMany, ManyToMany}}",
                            entity.name, field.name
                        ));
                    }

                    // To-many relationships cannot be optional
                    if is_to_many && field.optional {
                        critical_errors.push(format!(
                            "Entity '{}', field '{}': a to-many relationship \
                             (OneToMany, OrderedOneToMany, ManyToMany) cannot be optional",
                            entity.name, field.name
                        ));
                    }

                    // Weak OneToOne/ManyToOne must be optional (dangling pointer on delete)
                    let is_to_one = matches!(
                        field.relationship,
                        FieldRelationshipType::OneToOne | FieldRelationshipType::ManyToOne
                    );
                    if field.field_type == FieldType::Entity
                        && is_to_one
                        && !field.strong
                        && !field.optional
                    {
                        critical_errors.push(format!(
                            "Entity '{}', field '{}': a weak {:?} relationship \
                             must be optional (risk of dangling pointer when the \
                             referenced entity is deleted)",
                            entity.name, field.name, field.relationship
                        ));
                    }

                    // list_model requires a non-empty list_model_displayed_field
                    // that references an existing field of the target entity
                    if field.list_model {
                        let displayed = field.list_model_displayed_field.as_deref().unwrap_or("");
                        if displayed.is_empty() {
                            critical_errors.push(format!(
                                "Entity '{}', field '{}': list_model is true but \
                                 list_model_displayed_field is empty",
                                entity.name, field.name
                            ));
                        } else {
                            // Check that the target entity has a field with this name
                            if let Some(target_entity_id) = field.entity
                                && let Some(target_entity) = entity_by_id.get(&target_entity_id)
                            {
                                let target_field_names: Vec<&str> = target_entity
                                    .fields
                                    .iter()
                                    .filter_map(|fid| field_by_id.get(fid).map(|f| f.name.as_str()))
                                    .collect();
                                if !target_field_names.contains(&displayed) {
                                    critical_errors.push(format!(
                                        "Entity '{}', field '{}': list_model_displayed_field '{}' \
                                         does not exist in target entity '{}'",
                                        entity.name, field.name, displayed, target_entity.name
                                    ));
                                }
                            }
                        }
                    }

                    // Enum-type fields must have a valid enum_name and enum_values
                    if field.field_type == FieldType::Enum {
                        let en = field.enum_name.as_deref().unwrap_or("");
                        if en.is_empty() {
                            critical_errors.push(format!(
                                "Entity '{}', field '{}': field_type is Enum but enum_name is empty",
                                entity.name, field.name
                            ));
                        } else if !is_pascal_case(en) {
                            critical_errors.push(format!(
                                "Entity '{}', field '{}': enum_name '{}' must be PascalCase (expected '{}')",
                                entity.name, field.name, en, en.to_upper_camel_case()
                            ));
                        }
                        let vals = field.enum_values.as_slice();
                        if vals.is_empty() {
                            critical_errors.push(format!(
                                "Entity '{}', field '{}': field_type is Enum but enum_values is empty",
                                entity.name, field.name
                            ));
                        } else {
                            validate_enum_values(
                                vals,
                                &format!("Entity '{}', field '{}'", entity.name, field.name),
                                &entity_names,
                                &all_enum_names,
                                has_cpp_target,
                                &mut critical_errors,
                            );
                        }
                    }

                    // Entity-type fields must reference valid entities
                    if field.field_type == FieldType::Entity {
                        if let Some(ref_entity_id) = field.entity {
                            if !entity_by_id.contains_key(&ref_entity_id) {
                                critical_errors.push(format!(
                                    "Entity '{}', field '{}': references non-existent entity (id {})",
                                    entity.name, field.name, ref_entity_id
                                ));
                            }
                        } else {
                            critical_errors.push(format!(
                                "Entity '{}', field '{}': type is Entity but no entity reference set",
                                entity.name, field.name
                            ));
                        }
                    }
                }
            }

            // Minimum required fields: id (UInteger), created_at (DateTime), updated_at (DateTime)
            let has_id = all_entity_fields
                .iter()
                .any(|f| f.name == "id" && f.field_type == FieldType::UInteger);
            let has_created_at = all_entity_fields
                .iter()
                .any(|f| f.name == "created_at" && f.field_type == FieldType::DateTime);
            let has_updated_at = all_entity_fields
                .iter()
                .any(|f| f.name == "updated_at" && f.field_type == FieldType::DateTime);

            if !has_id {
                critical_errors.push(format!(
                    "Entity '{}': missing required field 'id' of type UInteger \
                     (either directly or via inheritance)",
                    entity.name
                ));
            }
            if !has_created_at {
                critical_errors.push(format!(
                    "Entity '{}': missing required field 'created_at' of type DateTime \
                     (either directly or via inheritance)",
                    entity.name
                ));
            }
            if !has_updated_at {
                critical_errors.push(format!(
                    "Entity '{}': missing required field 'updated_at' of type DateTime \
                     (either directly or via inheritance)",
                    entity.name
                ));
            }
        }

        // ── Relationships ──

        let all_relationship_ids: Vec<EntityId> = entities
            .iter()
            .flat_map(|e| e.relationships.clone())
            .collect();
        if !all_relationship_ids.is_empty() {
            let relationships = uow.get_relationship_multi(&all_relationship_ids)?;
            let relationships: Vec<Relationship> = relationships.into_iter().flatten().collect();

            // Track distinct strong parent entity types per child entity
            let mut strong_parents: HashMap<EntityId, HashMap<&str, Vec<&str>>> = HashMap::new();

            for rel in &relationships {
                let left_entity_id = &rel.left_entity.expect("Relationship missing left_entity");
                let right_entity_id = &rel.right_entity.expect("Relationship missing right_entity");

                if !entity_by_id.contains_key(left_entity_id) {
                    critical_errors.push(format!(
                        "Relationship '{}': left_entity (id {}) does not exist",
                        rel.field_name, left_entity_id
                    ));
                }
                if !entity_by_id.contains_key(right_entity_id) {
                    critical_errors.push(format!(
                        "Relationship '{}': right_entity (id {}) does not exist",
                        rel.field_name, right_entity_id
                    ));
                }

                // Only check Forward relationships to avoid double-counting
                if rel.strength == Strength::Strong && rel.direction == Direction::Forward {
                    // Undoable parent cannot have non-undoable strong child
                    if let (Some(parent), Some(child)) = (
                        entity_by_id.get(left_entity_id),
                        entity_by_id.get(right_entity_id),
                    ) && parent.undoable
                        && !child.undoable
                    {
                        critical_errors.push(format!(
                            "Entity '{}' is undoable but has a strong child '{}' \
                             that is not undoable (relationship '{}')",
                            parent.name, child.name, rel.field_name
                        ));
                    }

                    // Track strong parent type for multiple-parent check
                    if let Some(parent) = entity_by_id.get(left_entity_id) {
                        strong_parents
                            .entry(*right_entity_id)
                            .or_default()
                            .entry(&parent.name)
                            .or_default()
                            .push(&rel.field_name);
                    }
                }
            }

            // Check for entities with more than one strong parent entity type
            for (child_id, parent_types) in &strong_parents {
                if parent_types.len() > 1 {
                    let child_name = entity_by_id
                        .get(child_id)
                        .map(|e| e.name.as_str())
                        .unwrap_or("?");
                    let parent_list: Vec<String> = parent_types
                        .iter()
                        .map(|(name, rels)| format!("'{}' (via {})", name, rels.join(", ")))
                        .collect();
                    critical_errors.push(format!(
                        "Entity '{}' has multiple strong parents: {}. \
                         An entity can only have one strong owner",
                        child_name,
                        parent_list.join("; ")
                    ));
                }
            }

            // Weak references must not point to heritage-only entities
            // (except for the special "inherits_from" field)
            for rel in &relationships {
                if rel.strength == Strength::Weak && rel.direction == Direction::Forward {
                    if rel.field_name == "inherits_from" {
                        continue;
                    }
                    if let Some(target) = entity_by_id
                        .get(&rel.right_entity.expect("Relationship missing right_entity"))
                        && target.only_for_heritage
                    {
                        let left_entity_id =
                            &rel.left_entity.expect("Relationship missing left_entity");
                        let source_name = entity_by_id
                            .get(left_entity_id)
                            .map(|e| e.name.as_str())
                            .unwrap_or("?");
                        critical_errors.push(format!(
                            "Entity '{}', field '{}': references heritage-only entity '{}'. \
                             Only 'inherits_from' may reference a heritage-only entity",
                            source_name, rel.field_name, target.name
                        ));
                    }
                }
            }

            // Detect cyclic strong dependencies
            // Build adjacency list from strong Forward relationships (parent -> child)
            let mut strong_children: HashMap<EntityId, Vec<EntityId>> = HashMap::new();
            for rel in &relationships {
                if rel.strength == Strength::Strong && rel.direction == Direction::Forward {
                    let left_entity_id =
                        &rel.left_entity.expect("Relationship missing left_entity");
                    let right_entity_id =
                        &rel.right_entity.expect("Relationship missing right_entity");
                    strong_children
                        .entry(*left_entity_id)
                        .or_default()
                        .push(*right_entity_id);
                }
            }
            // DFS to detect cycles in the strong ownership graph
            let mut visited: HashSet<EntityId> = HashSet::new();
            let mut in_stack: HashSet<EntityId> = HashSet::new();
            let mut has_cycle = false;
            let all_entity_ids: Vec<EntityId> = entities.iter().map(|e| e.id).collect();
            for &start_id in &all_entity_ids {
                if visited.contains(&start_id) {
                    continue;
                }
                let mut stack: Vec<(EntityId, usize)> = vec![(start_id, 0)];
                in_stack.insert(start_id);
                while let Some((node, idx)) = stack.last_mut() {
                    let children = strong_children.get(node).cloned().unwrap_or_default();
                    if *idx < children.len() {
                        let child = children[*idx];
                        *idx += 1;
                        if in_stack.contains(&child) {
                            // Found a cycle — report it
                            let cycle_start_pos =
                                stack.iter().position(|(id, _)| *id == child).unwrap_or(0);
                            let cycle_names: Vec<&str> = stack[cycle_start_pos..]
                                .iter()
                                .filter_map(|(id, _)| entity_by_id.get(id).map(|e| e.name.as_str()))
                                .collect();
                            critical_errors.push(format!(
                                "Cyclic strong dependency detected: {} -> {}",
                                cycle_names.join(" -> "),
                                cycle_names.first().unwrap_or(&"?")
                            ));
                            has_cycle = true;
                            break;
                        }
                        if !visited.contains(&child) {
                            in_stack.insert(child);
                            stack.push((child, 0));
                        }
                    } else {
                        let (finished, _) = stack.pop().unwrap();
                        in_stack.remove(&finished);
                        visited.insert(finished);
                    }
                }
                if has_cycle {
                    break;
                }
                in_stack.clear();
            }
        }

        // ── Features ──

        let features = uow.get_feature_multi(&workspace.features)?;
        let features: Vec<Feature> = features.into_iter().flatten().collect();

        // Unique feature names (globally)
        let mut feature_names: HashSet<String> = HashSet::new();
        for feature in &features {
            if feature.name.is_empty() {
                critical_errors.push(format!("Feature with id {} has an empty name", feature.id));
            } else if !feature_names.insert(feature.name.clone()) {
                critical_errors.push(format!("Duplicate feature name: '{}'", feature.name));
            }
            // Forbidden names
            if let Some(reason) = is_forbidden_name(&feature.name) {
                critical_errors.push(format!(
                    "Feature '{}': name is a {} and cannot be used",
                    feature.name, reason
                ));
            }
            // snake_case check
            if !feature.name.is_empty() && !is_snake_case(&feature.name) {
                critical_errors.push(format!(
                    "Feature '{}': name must be snake_case (expected '{}')",
                    feature.name,
                    feature.name.to_snake_case()
                ));
            }
        }

        // ── Use cases ──

        let all_use_case_ids: Vec<EntityId> =
            features.iter().flat_map(|f| f.use_cases.clone()).collect();
        if !all_use_case_ids.is_empty() {
            let use_cases = uow.get_use_case_multi(&all_use_case_ids)?;
            let use_cases: Vec<UseCase> = use_cases.into_iter().flatten().collect();
            let uc_by_id: HashMap<EntityId, &UseCase> =
                use_cases.iter().map(|uc| (uc.id, uc)).collect();

            // Unique use case names within each feature
            for feature in &features {
                if feature.use_cases.is_empty() {
                    warnings.push(format!("Feature '{}' has no use cases", feature.name));
                    continue;
                }
                let mut uc_names_in_feature: HashSet<String> = HashSet::new();
                for uc_id in &feature.use_cases {
                    if let Some(uc) = uc_by_id.get(uc_id)
                        && !uc.name.is_empty()
                        && !uc_names_in_feature.insert(uc.name.clone())
                    {
                        critical_errors.push(format!(
                            "Feature '{}': duplicate use case name '{}' \
                             (must be unique within its feature)",
                            feature.name, uc.name
                        ));
                    }
                }
            }

            for uc in &use_cases {
                // Forbidden names
                if let Some(reason) = is_forbidden_name(&uc.name) {
                    critical_errors.push(format!(
                        "Use case '{}': name is a {} and cannot be used",
                        uc.name, reason
                    ));
                }
                // snake_case check
                if !uc.name.is_empty() && !is_snake_case(&uc.name) {
                    critical_errors.push(format!(
                        "Use case '{}': name must be snake_case (expected '{}')",
                        uc.name,
                        uc.name.to_snake_case()
                    ));
                }
            }

            // Check use case entity references
            for uc in &use_cases {
                for entity_id in &uc.entities {
                    if !entity_by_id.contains_key(entity_id) {
                        critical_errors.push(format!(
                            "Use case '{}': references non-existent entity (id {})",
                            uc.name, entity_id
                        ));
                    }
                }
            }

            // ── DTOs and DtoFields ──

            // Build mapping: use case id -> feature name
            let uc_to_feature: HashMap<EntityId, &str> = features
                .iter()
                .flat_map(|f| {
                    f.use_cases
                        .iter()
                        .map(move |&uc_id| (uc_id, f.name.as_str()))
                })
                .collect();

            // Unique DTO names per feature
            let mut dto_names_per_feature: HashMap<&str, HashSet<String>> = HashMap::new();

            for uc in &use_cases {
                let dto_ids: Vec<EntityId> =
                    [uc.dto_in, uc.dto_out].iter().flatten().copied().collect();
                let feature_name = uc_to_feature.get(&uc.id).copied().unwrap_or("?");

                for dto_id in dto_ids {
                    if let Some(dto) = uow.get_dto(&dto_id)? {
                        if dto.fields.is_empty() {
                            let which = if uc.dto_in == Some(dto_id) {
                                "dto_in"
                            } else {
                                "dto_out"
                            };
                            warnings.push(format!(
                                "Use case '{}': {} '{}' has no fields",
                                uc.name, which, dto.name
                            ));
                        }

                        // Unique DTO names within their feature
                        if !dto.name.is_empty() {
                            let names = dto_names_per_feature.entry(feature_name).or_default();
                            if !names.insert(dto.name.clone()) {
                                critical_errors.push(format!(
                                    "Feature '{}': duplicate DTO name '{}' \
                                     (must be unique within its feature)",
                                    feature_name, dto.name
                                ));
                            }
                        }

                        // Forbidden DTO names
                        if let Some(reason) = is_forbidden_name(&dto.name) {
                            critical_errors.push(format!(
                                "DTO '{}': name is a {} and cannot be used",
                                dto.name, reason
                            ));
                        }
                        // PascalCase check
                        if !dto.name.is_empty() && !is_pascal_case(&dto.name) {
                            critical_errors.push(format!(
                                "DTO '{}': name must be PascalCase (expected '{}')",
                                dto.name,
                                dto.name.to_upper_camel_case()
                            ));
                        }

                        // DtoField checks
                        if !dto.fields.is_empty() {
                            let dto_fields = uow.get_dto_field_multi(&dto.fields)?;
                            let dto_fields: Vec<DtoField> =
                                dto_fields.into_iter().flatten().collect();

                            // Collect enum names from DTO fields
                            for df in &dto_fields {
                                if df.field_type == DtoFieldType::Enum
                                    && let Some(ref en) = df.enum_name
                                {
                                    all_enum_names.insert(en.clone());
                                }
                            }

                            // Unique DtoField names within their owning DTO
                            let mut df_names: HashSet<String> = HashSet::new();
                            for df in &dto_fields {
                                if !df_names.insert(df.name.clone()) {
                                    critical_errors.push(format!(
                                        "DTO '{}': duplicate field name '{}'",
                                        dto.name, df.name
                                    ));
                                }
                                // Forbidden DtoField names
                                if let Some(reason) = is_forbidden_name(&df.name) {
                                    critical_errors.push(format!(
                                        "DTO '{}', field '{}': name is a {} and cannot be used",
                                        dto.name, df.name, reason
                                    ));
                                }
                                // snake_case check
                                if !df.name.is_empty() && !is_snake_case(&df.name) {
                                    critical_errors.push(format!(
                                        "DTO '{}', field '{}': name must be snake_case (expected '{}')",
                                        dto.name,
                                        df.name,
                                        df.name.to_snake_case()
                                    ));
                                }
                                // A DtoField cannot be both optional and is_list
                                if df.optional && df.is_list {
                                    critical_errors.push(format!(
                                        "DTO '{}', field '{}': cannot be both optional and is_list",
                                        dto.name, df.name
                                    ));
                                }
                                // Enum-type DtoFields must have a valid enum_name and enum_values
                                if df.field_type == DtoFieldType::Enum {
                                    let en = df.enum_name.as_deref().unwrap_or("");
                                    if en.is_empty() {
                                        critical_errors.push(format!(
                                            "DTO '{}', field '{}': field_type is Enum but enum_name is empty",
                                            dto.name, df.name
                                        ));
                                    } else if !is_pascal_case(en) {
                                        critical_errors.push(format!(
                                            "DTO '{}', field '{}': enum_name '{}' must be PascalCase (expected '{}')",
                                            dto.name, df.name, en, en.to_upper_camel_case()
                                        ));
                                    }
                                    let vals = df.enum_values.as_slice();
                                    if vals.is_empty() {
                                        critical_errors.push(format!(
                                            "DTO '{}', field '{}': field_type is Enum but enum_values is empty",
                                            dto.name, df.name
                                        ));
                                    } else {
                                        validate_enum_values(
                                            vals,
                                            &format!("DTO '{}', field '{}'", dto.name, df.name),
                                            &entity_names,
                                            &all_enum_names,
                                            has_cpp_target,
                                            &mut critical_errors,
                                        );
                                    }
                                }
                            }
                        }
                    } else {
                        critical_errors.push(format!(
                            "Use case '{}': DTO (id {}) not found",
                            uc.name, dto_id
                        ));
                    }
                }
            }
        }

        uow.end_transaction()?;

        Ok(CheckReturnDto {
            warnings,
            critical_errors,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::{collection_name_collisions, join_quoted_names};

    /// The entities of Qleany's own manifest, in declaration order.
    const QLEANY_ENTITIES: &[(&str, bool)] = &[
        ("Root", false),
        ("Workspace", false),
        ("System", false),
        ("Entity", false),
        ("Field", false),
        ("Feature", false),
        ("File", false),
        ("UseCase", false),
        ("Dto", false),
        ("DtoField", false),
        ("Global", false),
        ("Relationship", false),
        ("UserInterface", false),
    ];

    #[test]
    fn distinct_entity_names_usually_yield_distinct_collections() {
        assert_eq!(
            collection_name_collisions(&[("Entity", false), ("Feature", false)]),
            vec![]
        );
    }

    #[test]
    fn two_names_pluralizing_alike_collide() {
        assert_eq!(
            collection_name_collisions(&[("Base", false), ("Basis", false)]),
            vec![(
                "bases".to_string(),
                vec!["Base".to_string(), "Basis".to_string()]
            )]
        );
    }

    #[test]
    fn an_already_plural_name_collides_with_its_singular() {
        assert_eq!(
            collection_name_collisions(&[("Settings", false), ("Setting", false)]),
            vec![(
                "settings".to_string(),
                vec!["Setting".to_string(), "Settings".to_string()]
            )]
        );
    }

    #[test]
    fn an_irregular_plural_name_collides_with_its_singular() {
        assert_eq!(
            collection_name_collisions(&[("Child", false), ("Children", false)]),
            vec![(
                "children".to_string(),
                vec!["Child".to_string(), "Children".to_string()]
            )]
        );
    }

    #[test]
    fn heritage_only_entities_own_no_collection() {
        // 'Base' is never materialized, so it cannot clash with 'Basis'.
        assert_eq!(
            collection_name_collisions(&[("Base", true), ("Basis", false)]),
            vec![]
        );
    }

    #[test]
    fn empty_names_are_left_to_c03() {
        assert_eq!(
            collection_name_collisions(&[("", false), ("", false)]),
            vec![]
        );
    }

    #[test]
    fn a_duplicated_name_is_left_to_c04() {
        assert_eq!(
            collection_name_collisions(&[("Base", false), ("Base", false)]),
            vec![]
        );
    }

    #[test]
    fn more_than_two_names_are_reported_as_one_group() {
        assert_eq!(
            collection_name_collisions(&[("Index", false), ("Indice", false), ("Indices", false)]),
            vec![(
                "indices".to_string(),
                vec![
                    "Index".to_string(),
                    "Indice".to_string(),
                    "Indices".to_string()
                ]
            )]
        );
    }

    #[test]
    fn groups_are_sorted_by_collection_name() {
        let collisions = collection_name_collisions(&[
            ("Serie", false),
            ("Base", false),
            ("Series", false),
            ("Basis", false),
        ]);
        let collections: Vec<&str> = collisions.iter().map(|(c, _)| c.as_str()).collect();
        assert_eq!(collections, vec!["bases", "series"]);
    }

    #[test]
    fn qleany_own_entities_do_not_collide() {
        assert_eq!(collection_name_collisions(QLEANY_ENTITIES), vec![]);
    }

    #[test]
    fn names_are_joined_for_the_message() {
        assert_eq!(
            join_quoted_names(&["Base".to_string(), "Basis".to_string()]),
            "'Base' and 'Basis'"
        );
        assert_eq!(
            join_quoted_names(&["A".to_string(), "B".to_string(), "C".to_string()]),
            "'A', 'B' and 'C'"
        );
        assert_eq!(join_quoted_names(&["Base".to_string()]), "'Base'");
        assert_eq!(join_quoted_names(&[]), "");
    }
}
